def get_filepaths(repo, ignore_git_staged=False, include_git_unstaged=False):
    """
    Returns a list of file paths in the given git repository that are committed, staged, or unstaged.
    If ignore_git_staged is True, only committed files are returned.
    If include_git_unstaged is True, all committed, staged, and unstaged files are returned.
    """
    filepaths = []
    for root, dirs, files in os.walk(repo):
        for file in files:
            filepath = os.path.join(root, file)
            if is_ignored(repo, filepath):
                continue
            if is_committed(repo, filepath):
                filepaths.append(filepath)
            if not ignore_git_staged and is_staged(repo, filepath):
                filepaths.append(filepath)
            if include_git_unstaged and is_unstaged(repo, filepath):
                filepaths.append(filepath)
    return filepaths
